namespace{
int checks=0;
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);++checks;}
void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QTest::qWait(20);}
void valid(const Document& d){validate(d);check(decode(encode(d))==d,"Independent full caller native-valid BEFORE Window");}
void same(const Session& a,const Session& b){check(a.document()==b.document()&&encode(a.document())==encode(b.document())&&a.preview_document()==b.preview_document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation(),"Entire caller Session/native/History/preview/revision/generation unchanged");}
void write(const QString& path,const Document& d){QFile f(path);const auto b=encode(d);check(f.open(QIODevice::WriteOnly|QIODevice::NewOnly)&&f.write(b.data(),b.size())==static_cast<qint64>(b.size()),"Immutable actual or independent native retained once");}
QByteArray read(const QString& path){QFile f(path);check(f.open(QIODevice::ReadOnly),"Owned native bytes readable");return f.readAll();}
template<class T>T* control(Window& w,const QString& name){for(auto* c:w.findChildren<T*>(name))if(c->isVisible())return c;throw std::runtime_error("Original visible source producer missing");}
void reveal(QWidget* c){QPointer<QWidget> alive=c;for(auto* p=c->parentWidget();p;p=p->parentWidget())if(auto* s=qobject_cast<QScrollArea*>(p))s->ensureWidgetVisible(c);events();check(alive&&alive->isVisible()&&alive->isEnabled(),"Original source producer survives reveal and is enabled");}
ProcessingEntry& entry(Document& d){for(auto& e:d.objects.at("built").stack)if(e.id=="fill")return e;throw std::runtime_error("Independent exact paint entry missing");}
Document fixture(){
 Session setup(empty_document("gradient-mode-document","composition","artboard"));auto fill=default_operation("fill","nect.paint.fill");fill.parameters.at("r").literal=.125;fill.parameters.at("g").literal=.234;fill.parameters.at("g").expression=Expression{"0.23400000000000",1};fill.parameters.at("b").literal=.345;fill.parameters.at("b").binding=Binding{operation_ref("second","source-fill","b"),.75,.125,"copy_local_value"};fill.parameters.at("a").literal=.456;auto source=default_operation("source-fill","nect.paint.fill");source.parameters.at("r").literal=.8;source.parameters.at("b").literal=.2;Gradient g;g.id="gradient";g.start_x.literal=12.34567890123456;g.start_y.literal=2.34567890123456;g.end_x.literal=32.34567890123456;g.end_y.literal=3.34567890123456;GradientStop start,end;start.id="start";end.id="end";end.offset.literal=1;start.rgba[0].literal=.125;start.rgba[0].binding=Binding{operation_ref("second","source-fill","r"),.75,.125,"copy_local_value"};start.rgba[1].literal=.345;start.rgba[1].expression=Expression{"0.34500000000000",1};start.rgba[2].literal=.234;start.rgba[3].literal=.456;end.rgba[0].literal=.789;end.rgba[1].literal=.234;end.rgba[2].literal=.125;end.rgba[3].literal=.876;g.stops={end,start};fill.gradient=g;
 setup.apply({CreatePrimitive{"composition","","built","Built",default_primitive("shape","nect.shape.rectangle")},CreatePrimitive{"composition","","second","Second",default_primitive("source-shape","nect.shape.rectangle")},AddOperation{"second",source,1},AddOperation{"built",fill,1}},0);auto intended=setup.document();entry(intended).enabled_driver=operation_ref("second","source-fill","enabled");valid(intended);setup.apply({LinkOperationEnabled{operation_ref("built","fill","enabled"),operation_ref("second","source-fill","enabled"),false}},setup.revision());check(setup.document()==intended,"Manual full fixture paint enabled driver agrees dedicated typed command BEFORE Window");return setup.document();
}
void flow(const QString& root,int mode){
 const int action=mode%3,context=mode<3?-1:(mode-3)/3;const bool success=mode<3;auto initial=fixture();entry(initial).gradient->type=action==1?"radial":"linear";valid(initial);Session base(initial);auto intended=initial;if(action==2)entry(intended).gradient->enabled=false;else entry(intended).gradient->type=action==0?"radial":"linear";valid(intended);auto goal=base;goal.apply({SetGradient{"built","fill",entry(intended).gradient}},0);check(goal.document()==intended&&goal.revision()==1,"Independent manual full retained-mode Document agrees one atomic SetGradient BEFORE Window");auto undone=goal;undone.undo(1);auto redone=undone;redone.redo(2);check(undone.document()==initial&&redone.document()==intended,"Independent full retained Gradient native/ID/source UndoRedo BEFORE Window");
 auto replacement_doc=initial;replacement_doc.id="other-gradient-mode-document";valid(replacement_doc);Session replacement(replacement_doc);auto committed_doc=initial;committed_doc.objects.at("second").name="External committed rename";valid(committed_doc);auto changed=base;changed.apply({Rename{"second","External committed rename"}},0);check(changed.document()==committed_doc,"Independent full committed caller BEFORE Window");auto preview_doc=initial;preview_doc.objects.at("second").name="External caller preview";valid(preview_doc);auto active=base;active.begin_gesture(0);active.update_gesture({Rename{"second","External caller preview"}});check(active.document()==initial&&active.preview_document()==preview_doc&&active.history()==base.history()&&active.gesture_active()&&active.revision()==0,"Independent full active caller BEFORE Window");auto cancelled=active;cancelled.cancel_gesture();check(cancelled.document()==initial&&cancelled.preview_document()==initial&&cancelled.history()==base.history()&&cancelled.revision()==0&&!cancelled.gesture_active()&&cancelled.gesture_generation()==1,"Independent full cancelled caller BEFORE Window");
 auto frame_doc=initial;entry(frame_doc).gradient->start_x.literal+=1;valid(frame_doc);Session frame(frame_doc);auto style_doc=initial;entry(style_doc).parameters.at("a").literal=.567;valid(style_doc);Session style(style_doc);auto identity_doc=initial;entry(identity_doc).gradient->id="replacement-gradient";valid(identity_doc);Session identity(identity_doc);auto removed_doc=initial;entry(removed_doc).gradient.reset();valid(removed_doc);Session removed(removed_doc);auto removal=base;removal.apply({SetGradient{"built","fill",std::nullopt}},0);check(removal.document()==removed_doc,"Independent removed Gradient full Doc agrees canonical removal BEFORE Window");
 const Session* caller=&base;QString error;if(context==0){caller=&replacement;error="SESSION_CONFLICT";}if(context==1)error="SESSION_CONFLICT";if(context==2){caller=&changed;error="REVISION_CONFLICT";}if(context==3){caller=&active;error="GESTURE_ACTIVE";}if(context==4){caller=&cancelled;error="REVISION_CONFLICT";}if(context==5){caller=&cancelled;error="GESTURE_ACTIVE";}if(context==6){caller=&frame;error="PROPERTY_CONFLICT";}if(context==7){caller=&style;error="PROPERTY_CONFLICT";}if(context==8){caller=&identity;error="PROPERTY_CONFLICT";}if(context==9){caller=&removed;error="PROPERTY_CONFLICT";}
 const auto path=root+"/mode-"+QString::number(mode);write(path+"-expected.nect",intended);write(path+"-caller.nect",caller->document());QSettings settings(root+"/settings.ini",QSettings::IniFormat);Window w(path+"-recovery",std::make_unique<FolderLibrary>(settings),&settings);w.host.session=context==5?active:base;w.host.edited();w.resize(1400,1100);w.show();events();w.canvas->set_selection("built");events();auto* dock=w.findChild<QDockWidget*>("properties");check(dock,"Properties exists");dock->show();dock->raise();events();QPointer<QComboBox> combo=control<QComboBox>(w,"gradient-mode-fill");reveal(combo);const int before=action==1?2:1;check(combo&&combo->currentIndex()==before,"Original existing retained-gradient mode reflects exact initial authored state");const auto sid=w.host.session_id;w.host.session=*caller;if(context==1)w.host.session_id+="-other";same(w.host.session,*caller);QSignalSpy emitted(combo,qOverload<int>(&QComboBox::currentIndexChanged));QTest::keyClick(combo,action==0?Qt::Key_Down:Qt::Key_Up);events();check(emitted.count()==1,"One actual original retained Paint mode currentIndexChanged producer");const auto status=w.statusBar()->currentMessage();write(path+"-observed.nect",w.host.session.document());check(w.grab().save(path+"-status.png"),"Actual original mode/status Window rendered");std::cout<<"GRADIENT_MODE mode="<<mode<<" context="<<context<<" status="<<status.toStdString()<<" doc_equal="<<(w.host.session.document()==(success?goal.document():caller->document()))<<" history_equal="<<(w.host.session.history()==(success?goal.history():caller->history()))<<"\n";same(w.host.session,success?goal:*caller);
 if(!success){check(combo&&combo->currentIndex()==before&&status.startsWith(error+": "),"Original stale retained-mode selection rolls back and reports original-context refusal");if(w.host.session.gesture_active())w.host.session.cancel_gesture();w.host.session_id=sid;w.close();events();return;}
 check(status.isEmpty(),"Current retained-mode success reports no fabricated error");w.host.save(path+"-saved.nect");w.host.flush();events();same(w.host.session,goal);check(read(path+"-saved.nect")==read(path+"-expected.nect")&&QFile::copy(path+"-saved.nect",path+"-snapshot.nect"),"Actual immutable native preserves Gradient ID/frame/authored end-start stop order/bindings/expressions/paint fallback and enabled source");w.host.session.undo(w.host.session.revision());same(w.host.session,undone);w.host.session.redo(w.host.session.revision());same(w.host.session,redone);w.close();events();same(w.host.session,redone);
}
}
int main(int argc,char** argv){qputenv("QT_QPA_PLATFORM","windows");QApplication app(argc,argv);std::cout.setf(std::ios::unitbuf);try{std::cout<<"Native platform="<<QGuiApplication::platformName().toStdString()<<" PID="<<QCoreApplication::applicationPid()<<"\n";QTemporaryDir temp;check(temp.isValid(),"Owned scratch valid");const auto requested=qEnvironmentVariable("NECT_GRADIENT_MODE_ROOT"),root=requested.isEmpty()?temp.path():requested;int failures=0;for(int mode=0;mode<33;++mode){try{flow(root,mode);std::cout<<"CASE PASS mode="<<mode<<"\n";}catch(const std::exception& e){++failures;std::cerr<<"CASE FAIL mode="<<mode<<" reason="<<e.what()<<" checks="<<checks<<"\n";}}if(failures)throw std::runtime_error("Gradient mode cases failed: "+std::to_string(failures));std::cout<<"PASS Gradient mode "<<checks<<" checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL Gradient mode "<<e.what()<<" after "<<checks<<" checks\n";return 1;}}
